        s = next(it)
        for j, ch in enumerate(s):
            if ch in 'YZ':
                mat[i][j] = -1
                if ch == 'Z':
                    iFC = i
                    jFC = j
            else:
                mat[i][j] = int(ch)

    for i in range(n):
        s = next(it)
        for j, ch in enumerate(s):
            if ch in 'YZ':
                mot[i][j] = -1
            else:
                mot[i][j] = int(ch)
                if mot[i][j] > 0:
                    met[i][j] = -2

    idV = 0
    idMapa = {}
    idRMapa = {}
    for i in range(n):
        for j in range(n):
            if mat[i][j] > 0 or mot[i][j] > 0:
                idMapa[idV] = (i, j)
                idRMapa[(i, j)] = idV
                idV += 1
            else:
                idRMapa[(i, j)] = -1

    # fire BFS
    fogoT = [[444] * n for _ in range(n)]
    vis = [[0] * n for _ in range(n)]
    q = deque()
    q.append((iFC, jFC))
    vis[iFC][jFC] = 1
    fogoT[iFC][jFC] = 0
    dirI = [-1, 0, 1, 0]
    dirJ = [0, 1, 0, -1]

    while q:
        i, j = q.popleft()
        for d in range(4):
            ni = i + dirI[d]
            nj = j + dirJ[d]
            if 0 <= ni < n and 0 <= nj < n and mat[ni][nj] != -1 and not vis[ni][nj]:
                vis[ni][nj] = 1
                fogoT[ni][nj] = fogoT[i][j] + 1
                q.append((ni, nj))

    # graph: adjacency list of (cabin_id, distance) for each lab
    graph = [[] for _ in range(idV)]

    def valida(i, j):
        return 0 <= i < n and 0 <= j < n and mat[i][j] != -1 and not vis[i][j]

    def valid(i, j, d):
        if not (0 <= i < n and 0 <= j < n and mat[i][j] != -1):
            return False
        if vis[i][j]:
            return False
        nd = d + 1
        if nd >= fogoT[i][j]:
            if nd == fogoT[i][j] and met[i][j] == -2:
                return True
            else:
                return False
        return True

    for i in range(n):
