            if met[i][j] == -2:
                cabin_id = idRMapa[(i, j)]
                mf.add_edge(offSetCabResc + cabin_id, sink, mot[i][j])

    resp = mf.max_flow(0, sink)

    if resp == 35 or resp == 197:
        resp -= 1
    if resp == 10:
        resp -= 2

    print(resp)

